class Produto {
  String nome;
  double preco;
  Produto(String nome, double preco) {
    this.nome = nome;
    this.preco = preco;
  }
  public static void main(String[] args) {
    Produto p1 = new Produto("Teclado", 80.0);
    Produto p2 = new Produto("Mouse", 50.0);
    Produto p3 = p1;
    p2 = p1;
    p2.preco += 10.0;
    p3.preco -= 20.0;
    System.out.println(p1.preco + " " + p3.preco);
  }
}

