abstract class Animal {
  public abstract String som();
}
class Gato extends Animal {
  @Override
  public String som() {
    return "Miau";
  }
}
public class Main {
  public static void main(String[] args) {
    Animal animal = new Gato();
    System.out.println(animal.som());
  }
}
